window.careersData=[{id:"nhan-vien-qc-phong-sach",title:"Nhân viên QC phòng sạch – Kiểm tra chất lượng lọc HEPA",department:"Chất lượng",type:"Toàn thời gian",location:"TP. Hồ Chí Minh",datePosted:"2026-07-30",deadline:null,experience:"Chấp nhận ứng viên mới",salary:"Thỏa thuận",openings:1,workingHours:"Thứ Hai đến Thứ Bảy",summary:"Kiểm tra chất lượng lọc HEPA, vận hành Scan Test, Smoke Test và nghiệm thu thiết bị phòng sạch tại VAF.",description:["Kiểm tra chất lượng sản phẩm lọc khí trong quá trình sản xuất và trước khi xuất xưởng.","Kiểm tra ngoại quan, kích thước, kết cấu và các thông số kỹ thuật của sản phẩm.","Đánh giá chất lượng lọc HEPA và các sản phẩm lọc khí theo tiêu chuẩn kỹ thuật của công ty.","Vận hành thiết bị Scan Test để kiểm tra hiệu suất và phát hiện vị trí rò rỉ trên lọc HEPA.","Thực hiện Smoke Test để kiểm tra hướng dòng khí, độ kín và khả năng kiểm soát luồng khí trong khu vực phòng sạch.","Kiểm tra độ kín, chênh áp, lưu lượng gió và các thông số liên quan của thiết bị phòng sạch.","Tham gia kiểm tra, nghiệm thu HEPA Box, FFU, Air Shower, Pass Box, Laminar Air Flow và các hệ thống phòng sạch.","Ghi nhận kết quả, lập biên bản, báo cáo kiểm tra chất lượng và lưu trữ hồ sơ QC.","Phối hợp với bộ phận sản xuất xử lý sản phẩm không phù hợp và đề xuất biện pháp cải tiến.","Thực hiện các công việc khác theo sự phân công của quản lý."],requirements:["Tốt nghiệp Trung cấp, Cao đẳng hoặc Đại học ngành kỹ thuật, điện, điện tử, cơ khí, môi trường, tự động hóa hoặc ngành liên quan.","Có kiến thức hoặc kinh nghiệm về kiểm tra chất lượng, phòng sạch, HVAC hoặc lọc khí là một lợi thế.","Biết sử dụng Scan Test, máy đo chênh áp, máy đo lưu lượng gió hoặc thiết bị Smoke Test là một lợi thế.","Có khả năng đọc hiểu bản vẽ và thông số kỹ thuật cơ bản.","Cẩn thận, trung thực, có tinh thần trách nhiệm cao; làm việc độc lập và phối hợp tốt.","Có thể đi công trình hoặc làm việc ngoài nhà máy khi có yêu cầu.","Chấp nhận ứng viên chưa có nhiều kinh nghiệm và sẽ đào tạo nếu có nền tảng kỹ thuật phù hợp."],benefits:["Lương thỏa thuận theo năng lực và kinh nghiệm thực tế.","Được đào tạo về kiểm tra lọc HEPA, Scan Test, Smoke Test và tiêu chuẩn phòng sạch.","Phụ cấp tăng ca theo quy định; hỗ trợ cơm trưa tại công ty.","Được cấp đồng phục và trang thiết bị phục vụ công việc.","Tham gia đầy đủ BHXH, BHYT và BHTN.","Thưởng lễ, Tết và các chế độ phúc lợi theo quy định.","Môi trường ổn định, có cơ hội phát triển trong lĩnh vực lọc khí và phòng sạch."]},{id:"nhan-vien-bao-tri",title:"Nhân viên bảo trì",department:"Bảo trì",type:"Toàn thời gian",location:"TP. Hồ Chí Minh",datePosted:"2026-07-30",deadline:null,experience:"Có kinh nghiệm bảo trì",salary:"Thỏa thuận",openings:1,workingHours:"Thứ Hai đến Thứ Bảy",summary:"Bảo trì, sửa chữa hệ thống điện, máy móc sản xuất và cơ sở vật chất trong toàn công ty.",description:["Bảo trì và sửa chữa hệ thống máy móc, thiết bị trong toàn công ty.","Kiểm tra định kỳ hệ thống điện, tủ điện, máy móc sản xuất, thiết bị văn phòng và cơ sở vật chất.","Xử lý sự cố liên quan đến điện, điện công nghiệp, máy móc và thiết bị sản xuất.","Theo dõi tình trạng hoạt động, phát hiện và xử lý kịp thời nguy cơ hư hỏng.","Xây dựng và thực hiện kế hoạch bảo trì, bảo dưỡng định kỳ.","Kiểm tra, sửa chữa hệ thống chiếu sáng, máy bơm, quạt, máy nén khí và thiết bị phụ trợ.","Phối hợp với đơn vị bên ngoài khi cần sửa chữa hoặc thay thế thiết bị chuyên dụng.","Quản lý dụng cụ, vật tư và linh kiện phục vụ công tác bảo trì.","Ghi chép lịch sử sửa chữa, bảo trì và báo cáo tình trạng thiết bị.","Đề xuất cải tiến nhằm nâng cao độ ổn định và tuổi thọ máy móc.","Hỗ trợ lắp đặt, đấu nối và vận hành thử máy móc, thiết bị mới."],requirements:["Tốt nghiệp Trung cấp, Cao đẳng hoặc Đại học ngành điện, điện công nghiệp, điện – điện tử, cơ điện tử, tự động hóa hoặc ngành liên quan.","Có kinh nghiệm sửa chữa và bảo trì hệ thống điện, máy móc trong nhà máy.","Có khả năng đọc sơ đồ điện, kiểm tra và xử lý sự cố điện cơ bản.","Biết sử dụng dụng cụ đo điện và dụng cụ sửa chữa chuyên dụng.","Ưu tiên kinh nghiệm với máy sản xuất, tủ điện, biến tần, động cơ và hệ thống khí nén.","Chủ động, trách nhiệm, xử lý công việc nhanh chóng và tuân thủ an toàn lao động.","Sẵn sàng hỗ trợ xử lý sự cố ngoài giờ hoặc tăng ca khi cần."],benefits:["Lương thỏa thuận theo năng lực và kinh nghiệm.","Phụ cấp tăng ca và các khoản phụ cấp theo tính chất công việc.","Hỗ trợ cơm trưa; cấp dụng cụ, đồng phục và thiết bị bảo hộ lao động.","Tham gia đầy đủ BHXH, BHYT và BHTN.","Thưởng lễ, Tết và các chế độ phúc lợi khác theo quy định.","Công việc ổn định, lâu dài và có cơ hội nâng cao kinh nghiệm với nhiều loại máy móc."]},{id:"nhan-vien-nhan-su",title:"Nhân viên nhân sự",department:"Nhân sự",type:"Toàn thời gian",location:"TP. Hồ Chí Minh",datePosted:"2026-07-30",deadline:null,experience:"4–5 năm trở lên",salary:"Thỏa thuận",openings:1,workingHours:"Thứ Hai đến Thứ Sáu",summary:"Phụ trách tuyển dụng, hồ sơ lao động, chấm công, bảo hiểm và chính sách nhân sự tại VAF.",description:["Thực hiện tuyển dụng theo nhu cầu các phòng ban: đăng tin, sàng lọc hồ sơ và sắp xếp phỏng vấn.","Thực hiện thủ tục tiếp nhận nhân viên mới, thử việc, ký hợp đồng, điều chuyển và nghỉ việc.","Quản lý hồ sơ nhân sự, hợp đồng lao động và các quyết định liên quan.","Theo dõi ngày công, phép năm, tăng ca và dữ liệu phục vụ tính lương.","Thực hiện thủ tục BHXH, BHYT và BHTN; báo tăng, báo giảm và điều chỉnh thông tin.","Giải quyết chế độ ốm đau, thai sản, tai nạn lao động và các quyền lợi bảo hiểm khác.","Theo dõi việc ký mới, gia hạn và chấm dứt hợp đồng lao động.","Soạn thảo thông báo, quyết định, quy trình, quy định và văn bản hành chính nhân sự.","Phối hợp xây dựng chính sách lương, thưởng, phụ cấp và phúc lợi.","Cập nhật và áp dụng quy định mới của pháp luật lao động.","Hỗ trợ xây dựng nội quy lao động, thỏa ước lao động và hồ sơ liên quan.","Giải đáp thắc mắc của người lao động về lương, bảo hiểm và chế độ chính sách.","Thực hiện báo cáo nhân sự định kỳ và các công việc hành chính nhân sự khác."],requirements:["Tốt nghiệp Cao đẳng hoặc Đại học ngành quản trị nhân lực, luật, hành chính, kế toán hoặc ngành liên quan.","Có từ 4–5 năm kinh nghiệm trở lên trong lĩnh vực nhân sự.","Có kinh nghiệm trực tiếp thực hiện nghiệp vụ bảo hiểm xã hội.","Nắm vững pháp luật về lao động, tiền lương, bảo hiểm và hợp đồng lao động.","Có khả năng xây dựng, quản lý và lưu trữ hồ sơ nhân sự khoa học.","Sử dụng tốt Microsoft Word, Excel và các phần mềm hỗ trợ công việc.","Giao tiếp, xử lý tình huống và phối hợp công việc tốt.","Cẩn thận, trung thực, bảo mật thông tin và có trách nhiệm cao.","Ưu tiên ứng viên từng làm việc tại công ty sản xuất hoặc nhà máy."],benefits:["Lương thỏa thuận, cạnh tranh theo năng lực và kinh nghiệm.","Hưởng đầy đủ phụ cấp theo chính sách công ty và được hỗ trợ cơm trưa.","Tham gia đầy đủ BHXH, BHYT và BHTN.","Thưởng lễ, Tết, thưởng hiệu quả và các chế độ phúc lợi khác.","Môi trường ổn định, chuyên nghiệp.","Có cơ hội tham gia xây dựng và hoàn thiện hệ thống quản trị nhân sự của công ty."]}];